Set tValue = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.EACPacket.Record.EAC.Header).SystemIDLogicalToDisplay(pObject.EAC.Header.SystemID), tLen = $length(tValue)
If 4 > tLen {
	Set tPadding = $get(pPadArray(4 - tLen))
	If tPadding = "" {
		Set $piece(tPadding, $char(32), (4 - tLen + 1)) = ""
		Set pPadArray(4-tLen) = tPadding
	}
	Set tValue = tValue_tPadding
}
Do pStream.Write(tValue, 0, .tStatus)
